const columns=[{name:'Programming / APIs',test:/Python|TypeScript|C\+\+|API|Software|Backend|Programming/i},{name:'Networks / systems',test:/Routing|TCP|Network|Optics|Distributed|Linux|Systems|Cloud|Infrastructure|Robotics/i},{name:'Data / statistics',test:/Statistics|SQL|ML|Data|Experimental|RAG|Retrieval/i},{name:'Security / risk',test:/Risk|Threat|IAM|Security|Control|Governance|Cyber/i},{name:'People / product',test:/Communication|Consulting|Customer|Discovery|Delivery|Domain|Product/i},{name:'Testing / evaluation',test:/Evaluation|Test|Failure|Experimental|Monitoring|Observability/i}]
const mentions=(item:typeof roles[number],test:RegExp)=>test.test([...item.skills,...item.foundations].join(' '))
</script>
<template><section class="career-visuals"><figure class="learning-illustration"><img :src="withBase('/images/career-learning-workflow.png')" width="1920" height="819" loading="lazy" alt="Editorial illustration: students explore networking, security and applications, then build a small project, test it and share documented results."><figcaption>AI-generated editorial illustration of a learning workflow. It depicts a concept, not research evidence or a guaranteed career path.</figcaption></figure>
<h2>Choose a direction, then build evidence</h2><label class="context-metric">Role to investigate<select v-model="selected" aria-label="Learning path role"><option v-for="item in roles" :key="item.id" :value="item.id">{{item.title}}</option></select></label><ol class="learning-path" aria-live="polite"><li><span>01 / YOUR FOUNDATIONS</span><h3>{{role.foundations.join(' + ')}}</h3><p>Identify one example of work you can explain and one gap to practice.</p></li><li><span>02 / EXPLORE THE WORK</span><h3>{{role.title}}</h3><p>{{role.description}}</p><a :href="withBase(role.link)">Inspect the sourced profile →</a></li><li><span>03 / MAKE IT REVIEWABLE</span><h3>One small project with proof</h3><p>Choose the profile’s portfolio practice, define a baseline and tests, then publish observed failures and a clear README.</p><a :href="withBase('/jobs/')">Check actual job requirements →</a></li></ol><p>This is editorial learning guidance. Coursework and projects do not replace required degrees, authorization, professional experience or employer judgment.</p>
<h2>Compare the foundations across roles</h2><p>“Listed focus” means the short editorial skill/foundation summary mentions this area. A dash means it is absent from that short summary, not unnecessary or unimportant. These are not numeric skill scores or measured hiring frequencies. Role links lead to employer evidence.</p><div class="context-data-table" tabindex="0" aria-label="Scrollable qualitative skill matrix"><table><caption>Qualitative role/foundation map, reviewed November 5, 2026</caption><thead><tr><th scope="col">Role</th><th v-for="column in columns" :key="column.name" scope="col">{{column.name}}</th></tr></thead><tbody><tr v-for="item in roles" :key="item.id"><th scope="row"><a :href="withBase(item.link)">{{item.title}}</a></th><td v-for="column in columns" :key="column.name">{{mentions(item,column.test)?'Listed focus':'—'}}</td></tr></tbody></table></div></section></template>
